package stream

import (
	"iter"
	"maps"
)

// Generate2 an infinite sequential stream where each element pair is generated by the provided supplier function.
// Due to the stateful nature of the supplier, multiple operations towards the same stream might provide
// different results.
func Generate2[K comparable, V any](supplier func() (K, V)) *Stream2[K, V] {
	return &Stream2[K, V]{
		supply: func() iterator2[K, V] {
			return func() (K, V, bool) {
				k, v := supplier()
				return k, v, true
			}
		},
	}
}

// Iterate2 returns an infinite sequential ordered Stream2 produced by iterative application of a function
// f to an initial element seed, producing a Stream2 consisting of (keySeed, valSeed), f(keySeed, valSeed), f(f(keySeed, valSeed)), etc.
// The first element (position 0) in the Stream will be the provided (keySeed, valSeed) pair. For n > 0, the element at
// position n, will be the result of applying the function f to the element at position n - 1.
// Due to the stateful nature of the supplier, multiple operations towards the same stream might provide
// different results.
func Iterate2[K comparable, V any](keySeed K, valSeed V, f func(K, V) (K, V)) *Stream2[K, V] {
	return &Stream2[K, V]{
		supply: func() iterator2[K, V] {
			lastKey, lastVal := keySeed, valSeed
			return func() (K, V, bool) {
				k, v := lastKey, lastVal
				lastKey, lastVal = f(lastKey, lastVal)
				return k, v, true
			}
		},
	}
}

// Empty2 returns an empty stream
func Empty2[K comparable, V any]() *Stream2[K, V] {
	return &Stream2[K, V]{
		supply: func() iterator2[K, V] {
			return finishedIterator2[K, V]
		},
	}
}

// OfMap creates a Stream of item.Pair elements. Each kv.Pair corresponds to
// a key/value entry of the source map.
func OfMap[K comparable, V any](source map[K]V) *Stream2[K, V] {
	return OfSeq2(maps.All(source))
}

// OfSeq2 creates a Stream2[K, V] from a standard iter.Seq2[K, V] iterator.
func OfSeq2[K comparable, V any](source iter.Seq2[K, V]) *Stream2[K, V] {
	return &Stream2[K, V]{
		supply: func() iterator2[K, V] {
			pull, _ := iter.Pull2(source)
			return func() (K, V, bool) {
				k, v, ok := pull()
				return k, v, ok
			}
		},
	}
}

// Concat2 returns a lazily concatenated stream whose elements are
// all the elements of each of the provided Stream instances,
// following the provided order.
func Concat2[K comparable, V any](streams ...*Stream2[K, V]) *Stream2[K, V] {
	if len(streams) == 0 {
		return Empty2[K, V]()
	}
	return &Stream2[K, V]{
		supply: func() iterator2[K, V] {
			current, following := streams[0], streams[1:]
			next := current.iterator()
			return func() (K, V, bool) {
				for {
					k, v, ok := next()
					if ok {
						return k, v, true
					}
					if len(following) == 0 {
						return *new(K), *new(V), false
					}
					current, following = following[0], following[1:]
					next = current.iterator()
				}
			}
		},
	}
}
